```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

/// Convert days since 1970-01-01 to (year, month, day) in the proleptic Gregorian calendar.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = crate::wasi::clocks::wall_clock::now();
        let days = (now.seconds / 86_400) as i64;
        let (y, m, d) = civil_from_days(days);
        let y = y.clamp(0, 9999);
        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started: now.seconds,
        }
    }
}

export!(Node);
